#!/usr/bin/env Rscript
suppressPackageStartupMessages({library(dplyr);library(tidyr);library(readr);library(gt)})
a<-commandArgs(trailingOnly=TRUE);stopifnot(length(a)==1)
x<-read_csv(a[1],show_col_types=FALSE) |> filter(`FMP Area`=='BSAI')
stopifnot(all(x$`Trip Target Fishery` %in% c('Pollock - bottom','Pollock - midwater')))
x<-x |> mutate(in_scope=!grepl('Sculpin|^Squid$|^Birds -',`Species Group Name`,ignore.case=TRUE),column=case_when(`Species Group Name`=='Scypho jellies'~'Jellies',`Species Group Name`=='Misc fish'~'MiscFish',`Species Group Name`=='Sea star'~'SeaStar',`Species Group Name` %in% c('Capelin','Eulachon','Other osmerids','Smelt (Family Osmeridae)','Surf smelt')~'Osmerid',grepl('Grenadier',`Species Group Name`,ignore.case=TRUE)~'Grenadier',`Species Group Name`=='Eelpouts'~'Eelpouts',`Species Group Name`=='Sea pens whips'~'Sea.pen',`Species Group Name`=='Sea anemone unidentified'~'Anemone',`Species Group Name`=='Snails'~'Snails',TRUE~'Other'))
stopifnot(!anyNA(x$`Nontarget Estimate (mt)`[x$in_scope]))
s<-x |> filter(in_scope) |> group_by(Year,column) |> summarise(t=sum(`Nontarget Estimate (mt)`),.groups='drop') |> pivot_wider(names_from=column,values_from=t) |> select(Year,Jellies,MiscFish,SeaStar,Osmerid,Grenadier,Eelpouts,Sea.pen,Anemone,Snails,Other) |> arrange(Year)
write_csv(s,'2026/tables/nontarget-species-bycatch.csv',na='NA')
write_csv(x |> distinct(`Species Group Name`,in_scope,column) |> arrange(`Species Group Name`),'2026/tables/nontarget-species-column-map.csv')
write_csv(x |> group_by(Year,in_scope) |> summarise(records=n(),catch_mt=sum(`Nontarget Estimate (mt)`,na.rm=TRUE),missing_weight_records=sum(is.na(`Nontarget Estimate (mt)`)),last_week=max(`Week Ending Date`),.groups='drop'),'2026/tables/nontarget-species-coverage.csv')
stopifnot(all.equal(s |> mutate(total=rowSums(pick(-Year),na.rm=TRUE)) |> pull(total),x |> filter(in_scope) |> group_by(Year) |> summarise(t=sum(`Nontarget Estimate (mt)`),.groups='drop') |> arrange(Year) |> pull(t),tolerance=1e-10)==TRUE)
t<-s |> gt() |> fmt_number(columns=-Year,decimals=0,use_seps=TRUE) |> sub_missing(missing_text='NA') |> tab_options(table.font.names='Times New Roman',table.font.size=12,data_row.padding=2)
gtsave(t,'2026/tables/nontarget-species-bycatch.html',inline_css=TRUE)
print(s |> filter(Year>=2024),width=Inf)
